<?php
require 'page-guard.php'; if($_SESSION['user-role']!=='administrator'){http_response_code(403);exit('Administrators only.');}
require '../config/db_conn.php'; require '../includes/teacher-profile-schema.php'; require '../includes/student-placement-options.php'; require '../includes/section-catalog-schema.php'; ensureTeacherProfileColumns($conn); ensureSectionCatalogColumns($conn); seedDefaultTeacherSections($conn);
$firstName=trim($_POST['first_name']??''); $lastName=trim($_POST['last_name']??''); $name=trim($firstName.' '.$lastName); $user=trim($_POST['teacher_user']??''); $pass=$_POST['teacher_pass']??''; $confirm=$_POST['teacher_confirm']??''; $grade=(int)($_POST['grade']??0); $section=trim($_POST['section']??''); $strand=trim($_POST['strand']??''); $subject=trim($_POST['subject']??'');
$senior=in_array($grade,[11,12],true); $validAssignment=$senior ? ($subject===''&&in_array($strand,studentStrandsForGrade($grade),true)) : ($strand===''&&in_array($subject,teacherSubjects(),true));
if($firstName===''||$lastName===''||!filter_var($user,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$confirm||!isApprovedTeacherSection($conn,$grade,$strand,$section)||!$validAssignment)exit('Please provide valid teacher details, grade, section, and assignment.');
$hash=password_hash($pass,PASSWORD_DEFAULT); $stmt=$conn->prepare('INSERT INTO teachers (TEACHER_USER,TEACHER_PASS,TEACHER_NAME,FIRST_NAME,LAST_NAME,GRADE,STRAND,SECTION,SUBJECT) VALUES (?,?,?,?,?,?,?,?,?)'); $stmt->bind_param('sssssisss',$user,$hash,$name,$firstName,$lastName,$grade,$strand,$section,$subject);
if(!$stmt->execute()){http_response_code(409);exit('That teacher username already exists.');}
$_SESSION['toast']=['message'=>'Teacher account created successfully.','type'=>'success']; header('Location: teacher-list.php'); exit;
